'docs.im_add_param_host':'IMAP 服务器地址','docs.im_add_param_port':'端口，默认 993','docs.im_add_param_user':'邮箱用户名','docs.im_add_param_password':'邮箱密码或应用专用密码','docs.im_add_param_domain':'收件域名（需开启 catch-all）','docs.im_add_param_tls':'是否启用 TLS，默认 true',
