'docs.integration_title':'Integration Example','docs.integration_typical':'Typical Code Extraction Flow','docs.integration_step1':'// 1. Create inbox (auto-selects optimal provider, avoids blocked domains)','docs.integration_step2':'// 2. Use inbox address to register/verify on the target service','docs.integration_step4':'// 4. Report result (feeds auto-block rules and statistics)','docs.integration_step3':'// 3. Wait for the code and extract it','docs.response_200_text':'Response 200 (text/plain)','docs.example_paste_whole':'"<the whole paste>"','docs.example_app_password':'"<app-specific password>"','docs.example_appleid_password':'"<Apple ID password>"','docs.example_phones_optional':'// optional: list of phone numbers','docs.example_at_most_5':'// at most 5','docs.integration_curl_title':'cURL Quick Test','docs.integration_curl_wait_code':'# Wait for code','docs.integration_curl_outlook':'# Specify Outlook provider','docs.integration_curl_import':'# Import Outlook accounts',
